using System;
using System.Collections.Generic;
using Framework.AI.Core;
using Framework.Movement;
using Framework.Parameters;
using Game.AI.Actions;
using Game.AI.Core;
using Game.AI.Parameters;
using Game.AI.Perception;
using Game.Map;
using Game.Stage;
using UnityEngine;

namespace Game.Tests
{
    /// <summary>
    /// 自律型敵AIの統合動作を検証する。
    /// </summary>
    [DisallowMultipleComponent]
    public sealed class MazeEnemyAgentTest
        : MonoBehaviour
    {
        [Header("テスト設定")]

        [SerializeField]
        [Tooltip("テスト用ステージ管理Prefab。")]
        private MazeStageManager stageManagerPrefab;

        [SerializeField]
        [Tooltip("開始時にテストを実行する。")]
        private bool runTestsOnStart = true;

        [Header("テスト結果")]

        [SerializeField]
        [Tooltip("成功したテスト件数。")]
        private int passedCount;

        [SerializeField]
        [Tooltip("失敗したテスト件数。")]
        private int failedCount;

        /// <summary>
        /// 予定テスト件数。
        /// </summary>
        private const int ExpectedTestCount = 32;

        /// <summary>
        /// AI更新の経過時間。
        /// </summary>
        private const float TickInterval = 0.2f;

        /// <summary>
        /// 敵の初期座標。
        /// </summary>
        private static readonly Vector2Int StartPosition =
            new Vector2Int(3, 3);

        /// <summary>
        /// プレイヤーの識別子。
        /// </summary>
        private readonly Guid playerId = Guid.NewGuid();

        /// <summary>
        /// 脅威の識別子。
        /// </summary>
        private readonly Guid threatId = Guid.NewGuid();

        /// <summary>
        /// 認識対象候補の一覧。
        /// </summary>
        private readonly List<MazeEnemyTargetSnapshot> targets =
            new List<MazeEnemyTargetSnapshot>();

        /// <summary>
        /// テスト用ステージ。
        /// </summary>
        private MazeStageManager stageManager;

        /// <summary>
        /// テスト用移動オブジェクト。
        /// </summary>
        private GameObject movementObject;

        /// <summary>
        /// テスト用移動コントローラー。
        /// </summary>
        private GridMovementController movement;

        /// <summary>
        /// テスト用パラメーターセット。
        /// </summary>
        private ParameterSet<MazeEnemyParameter> parameters;

        /// <summary>
        /// テスト用敵AIコンテキスト。
        /// </summary>
        private MazeEnemyContext enemy;

        /// <summary>
        /// テスト対象の敵AI。
        /// </summary>
        private MazeEnemyAgent agent;

        /// <summary>
        /// 開始時にテストを実行する。
        /// </summary>
        private void Start()
        {
            if (runTestsOnStart)
            {
                RunAllTests();
            }
        }

        /// <summary>
        /// すべての統合テストを実行する。
        /// </summary>
        [ContextMenu("すべてのテストを実行")]
        public void RunAllTests()
        {
            if (!Application.isPlaying)
            {
                Debug.LogWarning(
                    "Play Modeで実行してください。",
                    this);

                return;
            }

            passedCount = 0;
            failedCount = 0;

            try
            {
                Prepare();
                TestInitialization();

                Prepare();
                TestRoutine();

                Prepare();
                TestChase();

                Prepare();
                TestEscape();

                Prepare();
                TestPause();

                Prepare();
                TestLifecycle();
            }
            catch (Exception exception)
            {
                failedCount++;

                Debug.LogException(exception, this);
            }
            finally
            {
                Cleanup();
            }

            Debug.Log(
                $"【MazeEnemyAgent テスト結果】\n" +
                $"成功：{passedCount}\n" +
                $"失敗：{failedCount}\n" +
                (passedCount == ExpectedTestCount &&
                 failedCount == 0
                    ? "すべてのテストに成功しました。"
                    : "失敗または未実行のテストがあります。"),
                this);
        }

        /// <summary>
        /// テスト環境を生成する。
        /// </summary>
        private void Prepare()
        {
            Cleanup();

            if (stageManagerPrefab == null)
            {
                throw new InvalidOperationException(
                    "テスト用ステージPrefabが未設定です。");
            }

            stageManager = Instantiate(stageManagerPrefab);

            if (!stageManager.GenerateStage())
            {
                throw new InvalidOperationException(
                    "ステージ生成に失敗しました。");
            }

            if (stageManager.Map.Width < 9 ||
                stageManager.Map.Height < 9)
            {
                throw new InvalidOperationException(
                    "9×9以上のマップが必要です。");
            }

            // 固定条件でテストするため全セルを床にする。
            stageManager.Map.Fill(MazeCell.CreateFloor());

            // ステージの即時クリアを防止する。
            stageManager.Map.SetCell(
                Vector2Int.zero,
                MazeCell.CreateFloor(MazeCellFlags.Gem));

            movementObject =
                new GameObject("EnemyAgentTest_Movement");

            movement = movementObject
                .AddComponent<GridMovementController>();

            movement.AutoUpdate = false;

            movement.Initialize(
                stageManager.CoordinateConverter,
                stageManager.IsWalkable,
                StartPosition);

            parameters =
                MazeEnemyParameterCatalog.CreateParameterSet();

            SetParameter(
                MazeEnemyParameter.MoveSpeed, 4f);

            SetParameter(
                MazeEnemyParameter.ChaseSpeedMultiplier, 1f);

            SetParameter(
                MazeEnemyParameter.EscapeSpeedMultiplier, 1.5f);

            SetParameter(
                MazeEnemyParameter.DetectionRange, 6f);

            SetParameter(
                MazeEnemyParameter.ThreatDetectionRange, 8f);

            SetParameter(
                MazeEnemyParameter.Aggression, 1f);

            SetParameter(
                MazeEnemyParameter.Caution, 1f);

            SetParameter(
                MazeEnemyParameter.Persistence, 1f);

            SetParameter(
                MazeEnemyParameter.TacticalIntelligence, 0f);

            SetParameter(
                MazeEnemyParameter.Territoriality, 0f);

            SetParameter(
                MazeEnemyParameter.PatrolPreference, 0f);

            SetParameter(
                MazeEnemyParameter.Exploration, 0f);

            var agentContext =
                new AgentContext<MazeEnemyParameter>(
                    "EnemyAgentTest",
                    parameters);

            enemy = new MazeEnemyContext(
                agentContext,
                stageManager,
                movement,
                StartPosition);

            agent = new MazeEnemyAgent(
                enemy,
                GetTargets);

            if (!agent.Initialize(agentContext))
            {
                throw new InvalidOperationException(
                    "敵AIの初期化に失敗しました。");
            }

            if (!stageManager.StartStage())
            {
                throw new InvalidOperationException(
                    "ステージ開始に失敗しました。");
            }

            if (!agent.Activate())
            {
                throw new InvalidOperationException(
                    "敵AIの有効化に失敗しました。");
            }
        }

        /// <summary>
        /// パラメーターの基本値を設定する。
        /// </summary>
        /// <param name="parameter">パラメーター識別子</param>
        /// <param name="value">設定値</param>
        private void SetParameter(
            MazeEnemyParameter parameter,
            float value)
        {
            parameters.SetBaseValue(parameter, value);
        }

        /// <summary>
        /// 認識対象候補を取得する。
        /// </summary>
        /// <returns>対象候補の一覧</returns>
        private IReadOnlyList<MazeEnemyTargetSnapshot>
            GetTargets()
        {
            return targets;
        }

        /// <summary>
        /// プレイヤーの認識対象候補を設定する。
        /// </summary>
        /// <param name="position">プレイヤー座標</param>
        private void SetPlayer(Vector2Int position)
        {
            targets.Clear();

            targets.Add(
                new MazeEnemyTargetSnapshot(
                    playerId,
                    MazeEnemyTargetType.Player,
                    position,
                    Vector2Int.zero,
                    0f));
        }

        /// <summary>
        /// 脅威の認識対象候補を設定する。
        /// </summary>
        /// <param name="position">脅威の座標</param>
        private void SetThreat(Vector2Int position)
        {
            targets.Clear();

            targets.Add(
                new MazeEnemyTargetSnapshot(
                    threatId,
                    MazeEnemyTargetType.Threat,
                    position,
                    Vector2Int.zero,
                    0f));
        }

        /// <summary>
        /// 巡回または探索を実行中であるか確認する。
        /// </summary>
        /// <returns>実行中の場合はtrue</returns>
        private bool IsRoutineAction()
        {
            return agent.CurrentAction ==
                       MazeEnemyActionType.Patrol ||
                   agent.CurrentAction ==
                       MazeEnemyActionType.Explore;
        }

        /// <summary>
        /// AIの思考更新を実行する。
        /// </summary>
        private void Think()
        {
            agent.Tick(TickInterval);
        }

        /// <summary>
        /// 思考と移動を指定回数実行する。
        /// </summary>
        /// <param name="count">更新回数</param>
        private void Simulate(int count)
        {
            for (int i = 0; i < count; i++)
            {
                Think();

                movement.Tick(TickInterval);
            }
        }

        /// <summary>
        /// 初期化と依存関係を検証する。
        /// </summary>
        private void TestInitialization()
        {
            bool initialized =
                agent.IsInitialized &&
                agent.IsActive &&
                agent.CanThink;

            Debug.Assert(initialized, "敵AI初期化", this);
            Check(initialized, "敵AI初期化");

            bool context =
                ReferenceEquals(
                    agent.EnemyContext, enemy) &&
                ReferenceEquals(
                    agent.Context, enemy.Agent);

            Debug.Assert(context, "コンテキスト接続", this);
            Check(context, "コンテキスト接続");

            bool perception =
                agent.Perception != null &&
                agent.Perception.IsValid;

            Debug.Assert(perception, "認識システム接続", this);
            Check(perception, "認識システム接続");

            bool evaluators =
                agent.Territory.IsValid &&
                agent.SpatialEvaluator.IsValid &&
                agent.TacticalEvaluator.IsValid;

            Debug.Assert(evaluators, "評価システム接続", this);
            Check(evaluators, "評価システム接続");

            bool utility =
                agent.Utility.IsValid &&
                agent.ActionContext.IsValid;

            Debug.Assert(utility, "行動評価と実行の接続", this);
            Check(utility, "行動評価と実行の接続");

            bool actions =
                agent.ActionController.Count == 7 &&
                !agent.HasCurrentAction;

            Debug.Assert(actions, "7種類の行動登録", this);
            Check(actions, "7種類の行動登録");
        }

        /// <summary>
        /// 自律巡回と探索を検証する。
        /// </summary>
        private void TestRoutine()
        {
            Think();

            bool selected = IsRoutineAction();

            Debug.Assert(selected, "自律移動行動の選択", this);
            Check(selected, "自律移動行動の選択");

            bool destination =
                agent.TryGetCurrentDestination(
                    out Vector2Int firstDestination) &&
                firstDestination != StartPosition;

            Debug.Assert(destination, "自律目的地の決定", this);
            Check(destination, "自律目的地の決定");

            bool following =
                agent.ActionContext.PathFollower.IsFollowing;

            Debug.Assert(following, "自律経路追従開始", this);
            Check(following, "自律経路追従開始");

            Think();

            bool retained =
                agent.TryGetCurrentDestination(
                    out Vector2Int nextDestination) &&
                nextDestination == firstDestination;

            Debug.Assert(retained, "巡回探索先の維持", this);
            Check(retained, "巡回探索先の維持");

            movement.Tick(0.3f);

            bool moved =
                movement.CurrentCell != StartPosition;

            Debug.Assert(moved, "敵AIの自律移動", this);
            Check(moved, "敵AIの自律移動");

            bool memory =
                enemy.SpatialMemory.VisitedPositionCount > 1;

            Debug.Assert(memory, "自律移動による訪問記憶", this);
            Check(memory, "自律移動による訪問記憶");
        }

        /// <summary>
        /// プレイヤー認識と追跡を検証する。
        /// </summary>
        private void TestChase()
        {
            Vector2Int playerPosition =
                new Vector2Int(5, 3);

            SetPlayer(playerPosition);

            Think();

            bool visible =
                agent.Perception.GetState(playerId) ==
                    MazeEnemyTargetState.Visible;

            Debug.Assert(visible, "プレイヤーの認識", this);
            Check(visible, "プレイヤーの認識");

            bool chase =
                agent.CurrentAction ==
                    MazeEnemyActionType.Chase;

            Debug.Assert(chase, "追跡行動の自律選択", this);
            Check(chase, "追跡行動の自律選択");

            bool destination =
                agent.TryGetCurrentDestination(
                    out Vector2Int result) &&
                result == playerPosition;

            Debug.Assert(destination, "認識座標への追跡", this);
            Check(destination, "認識座標への追跡");

            // 視界外へ移動した対象を設定する。
            SetPlayer(new Vector2Int(12, 8));

            Think();

            bool remembered =
                agent.Perception.TryGetObservation(
                    playerId,
                    out var observation) &&
                observation.IsRemembered &&
                observation.LastKnownPosition ==
                    playerPosition;

            Debug.Assert(remembered, "見失った対象の記憶", this);
            Check(remembered, "見失った対象の記憶");

            bool noOmniscience =
                agent.TryGetCurrentDestination(
                    out Vector2Int memoryDestination) &&
                memoryDestination == playerPosition;

            Debug.Assert(
                noOmniscience,
                "視界外の現在位置を追跡しない",
                this);

            Check(
                noOmniscience,
                "視界外の現在位置を追跡しない");

            targets.Clear();

            // 記憶座標まで移動する。
            movement.Tick(0.5f);

            Think();

            bool forgotten =
                movement.CurrentCell == playerPosition &&
                agent.Perception.GetState(playerId) ==
                    MazeEnemyTargetState.Unknown &&
                IsRoutineAction();

            Debug.Assert(
                forgotten,
                "記憶地点到着後の探索再開",
                this);

            Check(
                forgotten,
                "記憶地点到着後の探索再開");
        }

        /// <summary>
        /// 脅威認識と逃走を検証する。
        /// </summary>
        private void TestEscape()
        {
            Vector2Int threatPosition =
                new Vector2Int(4, 3);

            SetThreat(threatPosition);

            Think();

            bool detected =
                agent.Perception.GetState(threatId) ==
                    MazeEnemyTargetState.Visible;

            Debug.Assert(detected, "脅威の認識", this);
            Check(detected, "脅威の認識");

            bool escape =
                agent.CurrentAction ==
                    MazeEnemyActionType.Escape;

            Debug.Assert(escape, "逃走行動の自律選択", this);
            Check(escape, "逃走行動の自律選択");

            bool speed = Mathf.Approximately(
                movement.MoveSpeed, 6f);

            Debug.Assert(speed, "逃走速度の反映", this);
            Check(speed, "逃走速度の反映");

            bool destination =
                agent.TryGetCurrentDestination(
                    out Vector2Int result) &&
                Vector2Int.Distance(
                    result, threatPosition) >
                Vector2Int.Distance(
                    StartPosition, threatPosition);

            Debug.Assert(destination, "脅威から離れる目的地", this);
            Check(destination, "脅威から離れる目的地");
        }

        /// <summary>
        /// 一時停止と再開を検証する。
        /// </summary>
        private void TestPause()
        {
            Think();

            movement.Tick(0.1f);

            Vector3 previousPosition =
                movement.transform.position;

            MazeEnemyActionType previousAction =
                agent.CurrentAction;

            bool paused =
                agent.Pause() &&
                agent.IsPaused &&
                movement.IsPaused;

            Debug.Assert(paused, "敵AIの一時停止", this);
            Check(paused, "敵AIの一時停止");

            bool actionPaused =
                agent.ActionController.IsPaused;

            Debug.Assert(actionPaused, "行動管理の一時停止", this);
            Check(actionPaused, "行動管理の一時停止");

            long previousTickCount = agent.TickCount;

            Simulate(5);

            bool noThink =
                agent.TickCount == previousTickCount;

            Debug.Assert(noThink, "停止中の思考抑制", this);
            Check(noThink, "停止中の思考抑制");

            bool noMovement =
                movement.transform.position ==
                    previousPosition &&
                agent.CurrentAction == previousAction;

            Debug.Assert(noMovement, "停止中の移動抑制", this);
            Check(noMovement, "停止中の移動抑制");

            bool resumed =
                agent.Resume() &&
                agent.IsActive &&
                !movement.IsPaused &&
                !agent.ActionController.IsPaused;

            Debug.Assert(resumed, "敵AIの再開", this);
            Check(resumed, "敵AIの再開");

            movement.Tick(0.1f);

            bool moved =
                movement.transform.position !=
                    previousPosition;

            Debug.Assert(moved, "再開後の移動継続", this);
            Check(moved, "再開後の移動継続");
        }

        /// <summary>
        /// 破棄処理と所有権を検証する。
        /// </summary>
        private void TestLifecycle()
        {
            Think();

            bool deactivated =
                agent.Deactivate() &&
                !agent.IsActive &&
                !agent.HasCurrentAction &&
                !movement.IsMoving;

            Debug.Assert(deactivated, "敵AIの無効化", this);
            Check(deactivated, "敵AIの無効化");

            bool activated =
                agent.Activate() &&
                agent.CanThink;

            Debug.Assert(activated, "敵AIの再有効化", this);
            Check(activated, "敵AIの再有効化");

            var actionContext = agent.ActionContext;
            var perception = agent.Perception;
            var tactical = agent.TacticalEvaluator;
            var spatial = agent.SpatialEvaluator;
            var territory = agent.Territory;

            agent.Dispose();
            agent.Dispose();

            bool disposed =
                agent.IsDisposed &&
                actionContext.IsDisposed &&
                perception.IsDisposed &&
                tactical.IsDisposed &&
                spatial.IsDisposed &&
                territory.IsDisposed;

            Debug.Assert(disposed, "所有システムの破棄", this);
            Check(disposed, "所有システムの破棄");

            bool ownership =
                enemy.IsValid &&
                !parameters.IsDisposed &&
                movement.IsInitialized;

            Debug.Assert(ownership, "外部所有権の維持", this);
            Check(ownership, "外部所有権の維持");
        }

        /// <summary>
        /// テスト環境を解放する。
        /// </summary>
        private void Cleanup()
        {
            agent?.Dispose();
            agent = null;

            enemy?.Dispose();
            enemy = null;

            parameters?.Dispose();
            parameters = null;

            targets.Clear();

            if (movementObject != null)
            {
                movementObject.SetActive(false);
                Destroy(movementObject);

                movementObject = null;
            }

            movement = null;

            if (stageManager != null)
            {
                stageManager.gameObject.SetActive(false);
                Destroy(stageManager.gameObject);

                stageManager = null;
            }
        }

        /// <summary>
        /// オブジェクト破棄時に資源を解放する。
        /// </summary>
        private void OnDestroy()
        {
            Cleanup();
        }

        /// <summary>
        /// 個別テスト結果を出力する。
        /// </summary>
        /// <param name="passed">成功判定</param>
        /// <param name="testName">テスト名</param>
        private void Check(bool passed, string testName)
        {
            if (passed)
            {
                passedCount++;

                Debug.Log(
                    $"<color=#00CC66>【成功】</color> {testName}",
                    this);
            }
            else
            {
                failedCount++;

                Debug.LogError(
                    $"【失敗】{testName}",
                    this);
            }
        }
    }
}
